/* @autogenerated */
package net.civeira.phylax.feature.oauth.webauthn.application.usecase.finishregistration;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.Mockito;

import net.civeira.phylax.feature.identity.tenant.domain.Tenant;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserQueryRepositoryGateway;
import net.civeira.phylax.feature.oauth.webauthn.domain.WebAuthnChallenge;
import net.civeira.phylax.feature.oauth.webauthn.domain.WebAuthnCredential;
import net.civeira.phylax.feature.oauth.webauthn.domain.exception.WebAuthnException;
import net.civeira.phylax.feature.oauth.webauthn.domain.gateway.WebAuthnChallengeGateway;
import net.civeira.phylax.feature.oauth.webauthn.domain.gateway.WebAuthnCredentialGateway;
import net.civeira.phylax.feature.oauth.webauthn.domain.gateway.WebAuthnVerifierGateway;

class FinishRegistrationUsecaseUnitTest {
  private static final String ORIGIN = "https://idp.example.com";
  private static final String RP_ID = "idp.example.com";

  private final TenantQueryRepositoryGateway tenants =
      Mockito.mock(TenantQueryRepositoryGateway.class);
  private final UserQueryRepositoryGateway users = Mockito.mock(UserQueryRepositoryGateway.class);
  private final WebAuthnChallengeGateway challenges = Mockito.mock(WebAuthnChallengeGateway.class);
  private final WebAuthnCredentialGateway credentials =
      Mockito.mock(WebAuthnCredentialGateway.class);
  private final WebAuthnVerifierGateway verifier = Mockito.mock(WebAuthnVerifierGateway.class);
  private final Map<String, Object> credential = Map.of("id", "cred-1");

  private FinishRegistrationUsecase usecase;

  @BeforeEach
  void setUp() {
    Tenant tenant = Mockito.mock(Tenant.class);
    Mockito.when(tenant.isEnabled()).thenReturn(true);
    Mockito.when(tenant.getUid()).thenReturn("t-1");
    Mockito.when(tenants.find(Mockito.any())).thenReturn(Optional.of(tenant));
    User user = Mockito.mock(User.class);
    Mockito.when(user.getUid()).thenReturn("u-1");
    Mockito.when(user.getName()).thenReturn("ana");
    Mockito.when(user.getEmail()).thenReturn(Optional.of("ana@example.com"));
    Mockito.when(users.find(Mockito.any())).thenReturn(Optional.of(user));
    Mockito.when(verifier.verifyRegistration(credential, "chal", ORIGIN, RP_ID))
        .thenReturn(Map.of("credentialId", "cred-1", "publicKey", "pk", "signCount", 0));
    usecase = new FinishRegistrationUsecase(tenants, users, challenges, credentials, verifier);
  }

  private void challenge(String userUid, boolean verified) {
    OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC);
    Mockito.when(challenges.findById("c-1", "t-1"))
        .thenReturn(Optional.of(WebAuthnChallenge.builder().challengeId("c-1").tenantId("t-1")
            .userUid(userUid).challenge("chal").type("register").createdAt(now)
            .expiresAt(now.plusMinutes(5)).verified(verified).build()));
  }

  @Test
  @DisplayName("The passkey is stored for the user of the session and the challenge is consumed")
  void stores_for_session_user() {
    challenge("u-1", false);

    usecase.finish("c-1", "acme", "u-1", credential, ORIGIN, RP_ID, "Laptop");

    ArgumentCaptor<WebAuthnCredential> stored = ArgumentCaptor.forClass(WebAuthnCredential.class);
    Mockito.verify(credentials).store(stored.capture());
    Assertions.assertEquals("u-1", stored.getValue().getUserUid());
    Assertions.assertEquals("cred-1", stored.getValue().getCredentialId());
    ArgumentCaptor<WebAuthnChallenge> used = ArgumentCaptor.forClass(WebAuthnChallenge.class);
    Mockito.verify(challenges).markVerified(used.capture());
    Assertions.assertTrue(used.getValue().isVerified());
  }

  @Test
  @DisplayName("A challenge issued to another user is rejected before any verification")
  void rejects_challenge_of_another_user() {
    challenge("u-victim", false);

    Assertions.assertThrows(WebAuthnException.class,
        () -> usecase.finish("c-1", "acme", "u-1", credential, ORIGIN, RP_ID, "Laptop"));

    Mockito.verifyNoInteractions(verifier);
    Mockito.verify(credentials, Mockito.never()).store(Mockito.any());
  }

  @Test
  @DisplayName("A challenge already used can not register a second passkey")
  void rejects_used_challenge() {
    challenge("u-1", true);

    Assertions.assertThrows(WebAuthnException.class,
        () -> usecase.finish("c-1", "acme", "u-1", credential, ORIGIN, RP_ID, "Laptop"));

    Mockito.verify(credentials, Mockito.never()).store(Mockito.any());
  }
}
